/* ── Infinite Scroll Patch for posApp ── */
document.addEventListener('alpine:initialized', function () {
    var posEl = document.querySelector('[x-data="posApp()"]');
    if (!posEl) return;

    // Alpine.$data هو الـ API الرسمي في Alpine 3 للوصول للـ component
    var comp = window.Alpine.$data(posEl);
    if (!comp || comp.__isPatched) return;

    comp.__isPatched         = true;
    comp.hasMoreProducts     = false;
    comp.productsNextPage    = 1;
    comp.productsLoadingMore = false;
    comp._scrollHandler      = null;

    // ── Override loadProducts ─────────────────────────────────────────
    comp.loadProducts = async function () {
        this.productsLoading  = true;
        this.products         = [];
        this.hasMoreProducts  = false;
        this.productsNextPage = 1;
        this._detachScroll();

        try {
            var params = new URLSearchParams({ page: 1 });
            if (this.searchQuery) params.set('q', this.searchQuery);
            if (this.selectedCat && this.selectedCat !== '') params.set('category_id', this.selectedCat);

            var res  = await fetch('/pos/products/search?' + params, {
                credentials: 'same-origin',
                headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' }
            });
            var data = await res.json();

            this.products         = data.products  || [];
            this.hasMoreProducts  = data.hasMore   || false;
            this.productsNextPage = data.nextPage  || null;

            var self = this;
            // نعطي Alpine وقت يرسم المنتجات ثم نربط الـ scroll
            setTimeout(function () { self._attachScroll(); }, 200);

        } catch (e) {
            this.toast('خطأ في تحميل المنتجات', 'error');
        } finally {
            this.productsLoading = false;
        }
    };

    // ── Load Next Page ────────────────────────────────────────────────
    comp._loadMore = async function () {
        if (this.productsLoadingMore || !this.hasMoreProducts || !this.productsNextPage) return;
        this.productsLoadingMore = true;

        try {
            var params = new URLSearchParams({ page: this.productsNextPage });
            if (this.searchQuery) params.set('q', this.searchQuery);
            if (this.selectedCat && this.selectedCat !== '') params.set('category_id', this.selectedCat);

            var res  = await fetch('/pos/products/search?' + params, {
                credentials: 'same-origin',
                headers: { 'Accept': 'application/json', 'X-Requested-With': 'XMLHttpRequest' }
            });
            var data = await res.json();

            // نُضيف المنتجات الجديدة للمصفوفة الحالية
            var newProducts = data.products || [];
            for (var i = 0; i < newProducts.length; i++) {
                this.products.push(newProducts[i]);
            }

            this.hasMoreProducts  = data.hasMore  || false;
            this.productsNextPage = data.nextPage || null;

            if (!this.hasMoreProducts) this._detachScroll();

        } catch (e) {
            // صامت — المستخدم يحاول مجدداً بالتمرير
        } finally {
            this.productsLoadingMore = false;
        }
    };

    // ── Attach scroll listener on pos-grid ───────────────────────────
    comp._attachScroll = function () {
        this._detachScroll(); // نزيل القديم أولاً
        if (!this.hasMoreProducts) return;

        var grid = document.querySelector('.pos-grid');
        if (!grid) return;

        var self = this;
        this._scrollHandler = function () {
            if (self.productsLoadingMore || !self.hasMoreProducts) return;
            var fromBottom = grid.scrollHeight - grid.scrollTop - grid.clientHeight;
            if (fromBottom < 400) self._loadMore();
        };

        grid.addEventListener('scroll', this._scrollHandler, { passive: true });
    };

    comp._detachScroll = function () {
        if (!this._scrollHandler) return;
        var grid = document.querySelector('.pos-grid');
        if (grid) grid.removeEventListener('scroll', this._scrollHandler);
        this._scrollHandler = null;
    };

    // ── أعد التحميل فوراً بالدوال الجديدة ───────────────────────────
    comp.loadProducts();
});
